import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"Comandos","description":"","frontmatter":{},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md","lastUpdated":1781623519000}'),r={name:"reference/commands.md"};function n(s,t,c,i,l,m){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="comandos" tabindex="-1">Comandos <a class="header-anchor" href="#comandos" aria-label="Permalink to &quot;Comandos&quot;">​</a></h1><p>17 comandos, agrupados por etapa do ciclo. Notação <code>/sl.x</code> (Claude/Codex); em Grok e Antigravity, cada comando é exposto como a skill <code>sl-x</code>.</p><h2 id="gateway" tabindex="-1">Gateway <a class="header-anchor" href="#gateway" aria-label="Permalink to &quot;Gateway&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>O que faz</th></tr></thead><tbody><tr><td><strong><code>/sl</code></strong></td><td>Ponto de entrada inteligente. Responde dúvidas, guia o fluxo e sugere o próximo comando. Comece por aqui se estiver perdido.</td></tr></tbody></table><h2 id="descoberta" tabindex="-1">Descoberta <a class="header-anchor" href="#descoberta" aria-label="Permalink to &quot;Descoberta&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>O que faz</th></tr></thead><tbody><tr><td><strong><code>/sl.init</code></strong></td><td>Onboarding do projeto: coleta perfil do dono e gera o blueprint (<code>docs/owner.md</code>, <code>docs/product.md</code>).</td></tr><tr><td><strong><code>/sl.new</code></strong></td><td>Descoberta completa da feature + documentação: cria <code>about.md</code> com regras de negócio e escopo antes de qualquer código.</td></tr><tr><td><strong><code>/sl.brainstorm</code></strong></td><td>Parceiro de conversa para explorar ideias (READ-ONLY) — não altera arquivos.</td></tr></tbody></table><h2 id="planejamento" tabindex="-1">Planejamento <a class="header-anchor" href="#planejamento" aria-label="Permalink to &quot;Planejamento&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>O que faz</th></tr></thead><tbody><tr><td><strong><code>/sl.plan</code></strong></td><td>Orquestrador de planejamento técnico: cria <code>plan.md</code> com tarefas sequenciadas, mapa de arquivos e estimativas. Detecta épico vs. feature.</td></tr></tbody></table><h2 id="implementacao" tabindex="-1">Implementação <a class="header-anchor" href="#implementacao" aria-label="Permalink to &quot;Implementação&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>O que faz</th></tr></thead><tbody><tr><td><strong><code>/sl.build</code></strong></td><td>Executa a implementação coordenando subagentes (Backend, Frontend, Database). Não faz commit sozinho.</td></tr><tr><td><strong><code>/sl.autopilot</code></strong></td><td>Coordenador autônomo: roda planejamento → desenvolvimento → revisão sem interação.</td></tr></tbody></table><h2 id="qualidade" tabindex="-1">Qualidade <a class="header-anchor" href="#qualidade" aria-label="Permalink to &quot;Qualidade&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>O que faz</th></tr></thead><tbody><tr><td><strong><code>/sl.review</code></strong></td><td>Revisão de código com auto-correção até 100% (qualidade, OWASP, arquitetura, contratos).</td></tr><tr><td><strong><code>/sl.test</code></strong></td><td>Geração automática de testes mirando ~80% de cobertura; detecta o framework e roda em paralelo por área.</td></tr><tr><td><strong><code>/sl.audit</code></strong></td><td>Auditoria técnica completa: documentação, segurança, arquitetura, análise de dados.</td></tr><tr><td><strong><code>/sl.diagnose</code></strong></td><td>Triagem investigativa pré-decisão para sintomas ambíguos; recomenda a rota (hotfix/feature/no-action).</td></tr></tbody></table><h2 id="entrega" tabindex="-1">Entrega <a class="header-anchor" href="#entrega" aria-label="Permalink to &quot;Entrega&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>O que faz</th></tr></thead><tbody><tr><td><strong><code>/sl.done</code></strong></td><td>Finaliza o branch: changelog, documentação e merge (via <code>done.sh</code>).</td></tr><tr><td><strong><code>/sl.pull-request</code></strong></td><td>PR idempotente do branch atual: cria ou atualiza, gerando changelog da feature.</td></tr></tbody></table><h2 id="utilidades-ux" tabindex="-1">Utilidades &amp; UX <a class="header-anchor" href="#utilidades-ux" aria-label="Permalink to &quot;Utilidades &amp; UX&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>O que faz</th></tr></thead><tbody><tr><td><strong><code>/sl.hotfix</code></strong></td><td>Correção rápida de bug, com modo urgente para produção.</td></tr><tr><td><strong><code>/sl.xray</code></strong></td><td>Descoberta e mapeamento de arquitetura: classifica apps, despacha analisadores, consolida relatório.</td></tr><tr><td><strong><code>/sl.ux</code></strong></td><td>Refinamento leve de UX a partir de instruções livres.</td></tr><tr><td><strong><code>/sl.design</code></strong></td><td>Especialista de UX para SaaS: design mobile-first autônomo com fluxos de tela e specs de componentes.</td></tr></tbody></table><blockquote><p>Os comandos carregam <a href="/deep-dive/skills">skills</a> sob demanda e chamam o <a href="/deep-dive/project-structure">runtime</a> <code>.codesl/scripts</code> quando precisam de operações determinísticas (status, IDs, merge).</p></blockquote>',17)])])}const b=e(r,[["render",n]]);export{u as __pageData,b as default};
